import {registerDataRouterApp} from '@github-ui/react-core/register-app'
import {ruleInsightsDashboardAppBuilder} from './config/app-builder'

import {layoutRoute, orgLayoutRoute, stafftoolsLayoutRoute, stafftoolsOrgLayoutRoute} from './routes/layout-route'
import {Layout} from './routes/layout'
import {
  dashboardRoute,
  orgDashboardRoute,
  stafftoolsDashboardRoute,
  stafftoolsOrgDashboardRoute,
} from './routes/dashboard-route'
import {Dashboard} from './routes/dashboard'

export const ruleInsightsDashboardApp = ruleInsightsDashboardAppBuilder.createDataRouterAppFromRoutes([
  layoutRoute.toRoute({
    Component: Layout,
    children: [dashboardRoute.toRoute({Component: Dashboard})],
  }),
  orgLayoutRoute.toRoute({
    Component: Layout,
    children: [orgDashboardRoute.toRoute({Component: Dashboard})],
  }),
  stafftoolsLayoutRoute.toRoute({
    Component: Layout,
    children: [stafftoolsDashboardRoute.toRoute({Component: Dashboard})],
  }),
  stafftoolsOrgLayoutRoute.toRoute({
    Component: Layout,
    children: [stafftoolsOrgDashboardRoute.toRoute({Component: Dashboard})],
  }),
])
registerDataRouterApp(ruleInsightsDashboardApp)
