import {Suspense, lazy} from 'react'
import {Stack} from '@primer/react'
import {Blankslate} from '@primer/react/experimental'
import {ClockIcon} from '@primer/octicons-react'
import {useMatch} from '@github-ui/react-router'
import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {DashboardFilterBar} from '../components/DashboardFilterBar'
import {SkeletonChart} from '../components/SkeletonChart'
import {MetricCards} from '../components/MetricCards'
import {BypassesByRepoTable} from '../components/BypassesByRepoTable'
import {
  dashboardRoute,
  orgDashboardRoute,
  stafftoolsDashboardRoute,
  stafftoolsOrgDashboardRoute,
} from './dashboard-route'

type DashboardRouteConfig =
  | typeof dashboardRoute
  | typeof orgDashboardRoute
  | typeof stafftoolsDashboardRoute
  | typeof stafftoolsOrgDashboardRoute

const RuleSuitesChart = lazy(async () => ({
  default: (await import('../components/RuleSuitesChart')).RuleSuitesChart,
}))

const BypassesByActorChart = lazy(async () => ({
  default: (await import('../components/BypassesByActorChart')).BypassesByActorChart,
}))

const ColumnChartByCount = lazy(async () => ({
  default: (await import('../components/ColumnChartByCount')).ColumnChartByCount,
}))

export function Dashboard() {
  const orgMatch = useMatch(orgDashboardRoute.path)
  const stafftoolsMatch = useMatch(stafftoolsDashboardRoute.path)
  const stafftoolsOrgMatch = useMatch(stafftoolsOrgDashboardRoute.path)

  let routeConfig: DashboardRouteConfig = dashboardRoute
  if (orgMatch) {
    routeConfig = orgDashboardRoute
  } else if (stafftoolsMatch) {
    routeConfig = stafftoolsDashboardRoute
  } else if (stafftoolsOrgMatch) {
    routeConfig = stafftoolsOrgDashboardRoute
  }

  const {
    data: {sourceType, source, branchIsValid, filter, rulesets, timedOut, failuresByRuleset, failuresByRule},
  } = useRouteQuery(routeConfig, 'mainQuery')

  const isOrgLevel = sourceType === 'organization'

  return (
    <Stack>
      <DashboardFilterBar
        sourceType={sourceType}
        source={source}
        branchIsValid={branchIsValid}
        filter={filter}
        rulesets={rulesets}
      />
      {timedOut ? (
        <DashboardTimedOut />
      ) : (
        <>
          <Suspense fallback={<SkeletonChart />}>
            <RuleSuitesChart routeConfig={routeConfig} />
          </Suspense>
          <MetricCards routeConfig={routeConfig} />
          <Suspense fallback={<SkeletonChart />}>
            <BypassesByActorChart routeConfig={routeConfig} />
          </Suspense>
          {isOrgLevel && <BypassesByRepoTable routeConfig={routeConfig} />}
          {failuresByRuleset && (
            <Suspense fallback={<SkeletonChart />}>
              <ColumnChartByCount
                routeConfig={routeConfig}
                isClickable
                clickableFilterName="ruleset"
                title="Failures by ruleset"
                description="Top rulesets by failure count"
                yAxisTitle="Failures"
                xAxisTitle="Ruleset name"
                seriesData={failuresByRuleset}
                baseFilter={{rule_status: 'fail'}}
                maxColumns={5}
              />
            </Suspense>
          )}
          {failuresByRule && (
            <Suspense fallback={<SkeletonChart />}>
              <ColumnChartByCount
                routeConfig={routeConfig}
                title="Failures by rule"
                description="Top rules by failure count"
                yAxisTitle="Failures"
                xAxisTitle="Rule type"
                seriesData={failuresByRule}
                maxColumns={5}
              />
            </Suspense>
          )}
        </>
      )}
    </Stack>
  )
}

function DashboardTimedOut() {
  return (
    <Blankslate>
      <Blankslate.Visual>
        <ClockIcon size={24} />
      </Blankslate.Visual>
      <Blankslate.Heading>Rule insights search timed out</Blankslate.Heading>
      <Blankslate.Description>
        Try adjusting your filters or reducing the time range of your search
      </Blankslate.Description>
    </Blankslate>
  )
}
